{
  "claims": [
    {
      "claim_text": "By default the kubelet sends HTTP/2 requests for HTTP probes.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 states that by default the kubelet sends HTTP/1.1 requests, not HTTP/2.",
      "citations": [
        {
          "index": 0,
          "quote": "By default the `kubelet` sends HTTP/1.1 requests when executing an HTTP probe."
        }
      ]
    },
    {
      "claim_text": "Using HTTP/1.1 instead of HTTP/2 for HTTP probes requires the H2CContainerProbe feature gate.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 says that to use HTTP/2 cleartext (h2c) you must add the protocol field and enable the H2CContainerProbe feature gate; HTTP/1.1 is the default and does not require the gate.",
      "citations": [
        {
          "index": 0,
          "quote": "If your application serves health endpoints only over HTTP/2 cleartext (h2c), you can add the `protocol` field to the `httpGet` field in the probe specification and specify a value of `HTTP2`. This requires the `H2CContainerProbe` [feature gate](/docs/reference/command-line-tools-reference/feature-gates/) to be enabled on both the `kube-apiserver` and the `kubelet`."
        }
      ]
    },
    {
      "claim_text": "A TCP probe considers the container healthy if it can open a socket on the given port.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 directly states that if the kubelet can establish a connection, the container is considered healthy.",
      "citations": [
        {
          "index": 1,
          "quote": "If it can establish a connection, the container is considered healthy, if it can't it is considered a failure."
        }
      ]
    },
    {
      "claim_text": "If the readiness probe fails, the kubelet restarts the container.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 2 says that if the readiness probe fails, the pod is marked unready and does not receive traffic; it does not mention restarting the container.",
      "citations": [
        {
          "index": 2,
          "quote": "If the readiness probe fails, the pod will be marked unready and will not receive traffic from any services."
        }
      ]
    },
    {
      "claim_text": "gRPC probes connect over TLS by default.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 states that by default the kubelet connects to gRPC health endpoints over plaintext.",
      "citations": [
        {
          "index": 4,
          "quote": "By default the `kubelet` connects to gRPC health endpoints over plaintext."
        }
      ]
    },
    {
      "claim_text": "In TLS mode the kubelet verifies the server certificate.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 5 states that when mode is TLS, the kubelet uses InsecureSkipVerify and does not verify the server certificate.",
      "citations": [
        {
          "index": 5,
          "quote": "When `mode` is set to `TLS`, the `kubelet` connects over TLS with `InsecureSkipVerify` and does not verify the server certificate."
        }
      ]
    },
    {
      "claim_text": "The timeoutSeconds setting defaults to 1 second.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 mentions that timeoutSeconds defaults to 1s.",
      "citations": [
        {
          "index": 3,
          "quote": "does **not** respect the `timeoutSeconds` setting (which defaults to 1s)"
        }
      ]
    },
    {
      "claim_text": "If a startup probe never succeeds, the container keeps running but is never marked ready.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 6 states that if the startup probe never succeeds, the container is killed after 300s.",
      "citations": [
        {
          "index": 6,
          "quote": "If the startup probe never succeeds, the container is killed after 300s and subject to the pod's `restartPolicy`."
        }
      ]
    },
    {
      "claim_text": "Readiness probes only start after the liveness probe has succeeded.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 8 explicitly states that readiness and liveness probes do not depend on each other to succeed.",
      "citations": [
        {
          "index": 8,
          "quote": "The readiness and liveness probes do not depend on each other to succeed."
        }
      ]
    }
  ]
}
